const lesson = (id: string, title: string, summary: string, structureIds: string[], cues: string[], landmarks: string[], relationships: string[], confusions: string[], sourceId: string): Lesson => ({ id,title,summary,structureIds,recognitionCues:cues,landmarks,relationships,commonConfusions:confusions,sourceIds:[sourceId] });

export const cellsLessons: Lesson[] = [
  lesson('cell-boundaries-organelles','Cell boundaries and organelles','Use membrane shape and organelle distribution to orient a cell.',['cell-membrane','cytoplasm','nucleus-cell','nucleolus-cell','chromatin-cell','nuclear-envelope','ribosome-cell','rough-er-cell','smooth-er-cell','golgi-apparatus-cell','mitochondrion-cell','lysosome-cell','peroxisome-cell','centrosome-cell'],['A nucleus is usually the largest conspicuous compartment; rough ER has ribosomes. Smooth ER lacks ribosomes and mitochondria have a double membrane with internal cristae.'],['The nuclear envelope surrounds chromatin; the nucleolus is a dense region within the nucleus, and Golgi stacks sit in the secretory pathway.'],['Membrane-bound compartments separate chemical work; ribosomes build proteins, lysosomes digest material, and centrosomes organize microtubules.'],['Cytoplasm is the region outside the nucleus, not a single organelle.'], 'source-openstax-ap-2013-cells-tissues'),
  lesson('cell-surface-junctions','Cell surfaces and junctions','Distinguish apical specializations and junctions by what they permit or prevent.',['microvillus-cell','tight-junction-cell','desmosome-cell','gap-junction-cell','hemidesmosome-cell','basement-membrane-tissue'],['Tight junctions form seals; gap junctions are communication channels.'],['Hemidesmosomes anchor basal cells to basement membrane.'],['Junction choice predicts barrier strength, mechanical coupling, or signaling.'],['Desmosomes join cells; hemidesmosomes attach a cell to its basal support.'], 'source-openstax-ap-2013-cells-tissues'),
  lesson('epithelial-patterns','Epithelial tissue patterns','Count layers and identify the apical cell shape before naming an epithelium.',['simple-squamous-epithelium','simple-cuboidal-epithelium','simple-columnar-epithelium','pseudostratified-epithelium','stratified-squamous-keratinized','stratified-squamous-nonkeratinized','stratified-cuboidal-epithelium','stratified-columnar-epithelium','transitional-epithelium','basement-membrane-tissue','goblet-cell-tissue'],['Simple means one layer; pseudostratified looks layered but contacts the basement membrane.'],['Apical cells determine squamous, cuboidal, or columnar naming; goblet cells are pale secretory cells.'],['Layer count reflects protection versus exchange or secretion.'],['Pseudostratified is not truly stratified; transitional cells change shape with stretch.'], 'source-openstax-ap-2013-cells-tissues'),
  lesson('glandular-epithelium','Glandular epithelium and ducts','Distinguish secretory epithelium by whether products enter a duct or surrounding fluid.',['exocrine-gland-tissue','endocrine-gland-tissue','duct-gland-tissue'],['Exocrine glands retain a duct; endocrine glands are ductless. Secretory cells cluster around a lumen in an exocrine unit, whereas endocrine cells lie close to capillaries.'],['A duct connects an exocrine secretory unit to an epithelial surface; the duct is the conducting passage, not the secretory portion.'],['Gland organization predicts whether secretion reaches a surface through a duct or enters interstitial fluid for nearby blood vessels.'],['A goblet cell is a unicellular exocrine gland, not an endocrine cell; a duct is not itself the glandular secretory unit.'], 'source-openstax-ap-2013-cells-tissues'),
  lesson('connective-matrices','Connective tissue matrices','Recognize connective tissues by fibers, ground substance, and cells rather than surface shape.',['areolar-connective-tissue','adipose-connective-tissue','reticular-connective-tissue','dense-regular-connective-tissue','dense-irregular-connective-tissue','elastic-connective-tissue','hyaline-cartilage-tissue','elastic-cartilage-tissue','fibrocartilage-tissue','osteocyte-tissue','bone-tissue','blood-tissue','erythrocyte-tissue','leukocyte-tissue','platelet-tissue','collagen-fiber-tissue','elastic-fiber-tissue','lacuna-tissue'],['Parallel collagen suggests dense regular tissue; empty-looking spaces may be lacunae. Loose areolar tissue has more open ground substance, while adipose cells appear as large clear storage spaces.'],['Reticular fibers form a delicate supporting network; cartilage cells and osteocytes sit in lacunae; blood formed elements are suspended in plasma. Collagen fibers resist tension, whereas elastic fibers recoil.'],['Matrix composition determines tensile strength, flexibility, or fluid transport; erythrocytes carry oxygen, leukocytes defend, and platelets participate in clotting.'],['Dense regular and irregular differ in fiber orientation; elastic cartilage is not hyaline cartilage. Formed elements are suspended cells or cell fragments, not the blood matrix itself.'], 'source-openstax-ap-2013-cells-tissues'),
  lesson('muscle-histology','Muscle tissue cues','Use striations, branching, and control style to separate the three muscle tissues.',['skeletal-muscle-tissue','cardiac-muscle-tissue','smooth-muscle-tissue','intercalated-disc-tissue'],['Skeletal fibers are striated and long; cardiac fibers branch and show intercalated discs.'],['Intercalated discs are cardiac landmarks; smooth muscle lacks visible striations.'],['All contract, but architecture matches voluntary movement, pumping, or organ-wall control.'],['Cardiac is striated but not skeletal; smooth does not mean noncontractile.'], 'source-openstax-ap-2013-cells-tissues'),
  lesson('nervous-tissue-cues','Nervous tissue cues','Separate signal-conducting neurons from supporting neuroglia in a tissue field.',['neuron-tissue','neuroglia-tissue'],['A neuron has a prominent soma with processes; glia are smaller supporting cells.'],['Neural tissue may show cell bodies among many small nuclei.'],['Neurons communicate; neuroglia maintain the local environment and support signaling.'],['A small nucleus alone is not enough to label a neuron.'], 'source-openstax-ap-2013-cells-tissues'),
  lesson('histology-recognition','Integrated histology recognition','Combine boundary, matrix, and cell-shape cues to make a defensible tissue call.',['simple-squamous-epithelium','stratified-squamous-keratinized','hyaline-cartilage-tissue','skeletal-muscle-tissue','cardiac-muscle-tissue','neuron-tissue','collagen-fiber-tissue'],['Start with organization: sheet, matrix, parallel fibers, or excitable cells.'],['Keratinized apical layers, lacunae, striations, and intercalated discs are high-yield cues.'],['A tissue label should follow visible structure and expected function.'],['Do not identify tissue from one isolated nucleus or stain color alone.'], 'source-openstax-ap-2013-cells-tissues'),
];

export const skinLessons: Lesson[] = [
  lesson('skin-layers-strata','Skin layers and epidermal strata','Read skin from superficial epidermis toward deeper dermis and hypodermis.',['epidermis-skin','dermis-skin','hypodermis-skin','stratum-basale','stratum-spinosum','stratum-granulosum','stratum-lucidum','stratum-corneum'],['Stratum corneum is superficial; stratum basale contacts the basement boundary.'],['Lucidum is a clear layer in thick skin; papillary dermis lies above reticular dermis.'],['Layer position predicts keratinization, nourishment, and mechanical support.'],['Hypodermis is not a layer of the epidermis; lucidum is not present in all skin.'], 'source-openstax-ap-2013-integument'),
  lesson('epidermal-cells','Epidermal cell types','Match epidermal cells to barrier, pigment, immune, or tactile roles.',['keratinocyte-skin','melanocyte-skin','merkel-cell-skin','langerhans-cell-skin'],['Keratinocytes dominate; melanocytes have pigment-containing processes.'],['Basale contains renewing cells and melanocytes; Merkel cells associate with touch.'],['Cell type explains the visual and sensory function of each epidermal region.'],['Melanin is produced by melanocytes, not keratinocytes, although keratinocytes receive it.'], 'source-openstax-ap-2013-integument'),
  lesson('dermis-hypodermis','Dermis and hypodermis','Use papillary/reticular organization and subcutaneous fat to orient deeper skin.',['papillary-layer-skin','reticular-layer-skin','dermal-papilla-skin','collagen-skin','elastic-fibers-skin','cutaneous-blood-vessels-skin','hypodermis-skin'],['Papillary dermis is superficial and loose; reticular dermis is deeper and denser.'],['Dermal papillae interlock with epidermis; collagen and elastic fibers support recoil; vessels course through the dermis.'],['Hypodermis cushions and anchors skin beneath the dermis; dermal vessels help support epidermal cells.'],['Dermis is connective tissue; hypodermis is not simply “deep dermis.”'], 'source-openstax-ap-2013-integument'),
  lesson('cutaneous-glands','Cutaneous glands','Separate sweat, oil, and specialized glands by duct route and secretion.',['eccrine-sweat-gland','apocrine-sweat-gland','sebaceous-gland-skin','ceruminous-gland-skin','sweat-pore-skin','sebaceous-duct-skin'],['Eccrine ducts reach the surface; sebaceous glands associate with follicles.'],['Ceruminous glands occur in the external acoustic meatus; apocrine ducts enter follicles; sebaceous ducts lead toward follicles.'],['Secretions influence cooling, lubrication, scent, and ear-canal protection.'],['Sebum is not sweat; an apocrine gland is not an eccrine duct.'], 'source-openstax-ap-2013-integument'),
  lesson('hair-nails','Hair and nails','Identify keratinized appendages by their growth region and attachment.',['hair-shaft-skin','hair-root-skin','hair-follicle-skin','hair-bulb-skin','dermal-papilla-hair','arrector-pili-skin','nail-plate-skin','nail-bed-skin','nail-root-skin','nail-matrix-skin'],['The shaft projects above the surface; the bulb is the expanded base of a follicle.'],['The nail matrix produces the plate; arrector pili attach follicle to dermis.'],['Matrix and bulb regions support growth; follicles house hair roots.'],['Nail bed supports the plate but does not equal nail matrix; root is not shaft.'], 'source-openstax-ap-2013-integument'),
  lesson('skin-sensation-function','Skin sensation and functions','Relate receptor location and skin structures to touch, temperature, protection, and vascular support.',['tactile-corpuscle-skin','lamellated-corpuscle-skin','free-nerve-ending-skin','hair-root-plexus-skin','cutaneous-blood-vessels-skin','collagen-skin'],['Tactile corpuscles are superficial; lamellated corpuscles are deeper and onion-like.'],['Free endings extend into epidermis; hair-root plexuses wrap follicles; dermal vessels support tissue beneath the avascular epidermis.'],['Skin is barrier, thermoregulatory organ, sensory interface, and site of vitamin D precursor production.'],['A receptor is not a gland; “deep pressure” is not the same cue as light touch.'], 'source-openstax-ap-2013-integument'),
];

export const sensesLessons: Lesson[] = [
  lesson('eye-coats','Eye coats and chambers','Orient the globe by its fibrous, vascular, and neural coats, then locate the fluid spaces.',['fibrous-tunic-eye','sclera-eye','cornea-eye','vascular-tunic-eye','choroid-eye','ciliary-body-eye','iris-eye','pupil-eye','anterior-chamber-eye','posterior-chamber-eye','aqueous-humor-eye','vitreous-chamber-eye','vitreous-humor-eye'],['Sclera is opaque and posterior; cornea is transparent and anterior. The vascular tunic includes choroid, ciliary body, and iris.'],['Iris surrounds pupil; aqueous humor occupies anterior and posterior chambers, while vitreous humor fills the chamber behind the lens.'],['Coats protect and nourish while chambers maintain optical geometry; the ciliary body links the vascular coat to lens support.'],['Pupil is an opening, not a muscle; vitreous chamber is behind the lens, not between cornea and iris.'], 'source-openstax-ap-2013-special-senses'),
  lesson('lens-retina','Lens and retina','Trace light from cornea to photoreceptors and distinguish the central pit from the blind spot.',['lens-eye','suspensory-ligaments-eye','retina-eye','retinal-pigment-epithelium-eye','optic-disc-eye','fovea-centralis-eye','macula-lutea-eye','rods-eye','cones-eye','bipolar-cells-eye','ganglion-cells-eye'],['Fovea is the sharp-vision center; optic disc lacks photoreceptors. The lens is held by suspensory ligaments, and rods are more suited to dim light while cones support color and acuity.'],['The pigment epithelium lies external to photoreceptors; light reaches rods and cones before signals pass to bipolar cells and ganglion cells whose axons form the optic nerve.'],['Lens shape changes focus; retinal circuits convert light into neural signals, with the fovea specialized for the densest cone sampling.'],['Macula surrounds the fovea; optic disc is not the fovea or pigment epithelium, and ganglion cells are not photoreceptors.'], 'source-openstax-ap-2013-special-senses'),
  lesson('eye-accessory-structures','Accessory eye structures and lacrimal drainage','Identify the protective surface structures around the globe and follow the tear pathway.',['eyelid-sense','conjunctiva-sense','lacrimal-gland-sense','lacrimal-sac-sense','nasolacrimal-duct-sense'],['The eyelid covers the anterior globe; conjunctiva is a thin lining rather than the cornea. Its palpebral and bulbar portions reflect over the inner lid and anterior sclera.'],['Lacrimal gland is superolateral; tears cross the conjunctival sac to medial puncta, canaliculi, lacrimal sac, and nasolacrimal duct before entering the nasal cavity.'],['Accessory structures protect, lubricate, and clear the exposed eye surface; puncta and canaliculi lead tears to the sac, then the duct drains them into the nasal cavity.'],['Conjunctiva does not cover the cornea; lacrimal drainage is not the aqueous-humor pathway, and canaliculi are not the lacrimal sac or gland.'], 'source-openstax-ap-2013-special-senses'),
  lesson('extraocular-movement','Extraocular muscles and pathways','Pair muscle names with eye movements and their motor nerves.',['medial-rectus-eye','lateral-rectus-eye','superior-rectus-eye','inferior-rectus-eye','superior-oblique-eye','inferior-oblique-eye','levator-palpebrae-eye','oculomotor-nerve-sense','trochlear-nerve-sense','abducens-nerve-sense'],['Medial rectus adducts; lateral rectus abducts.'],['Trochlear nerve supplies superior oblique; abducens supplies lateral rectus.'],['Coordinated muscles keep both visual axes aligned.'],['Abduction is lateral movement, not eyelid elevation; optic nerve is sensory, not motor.'], 'source-openstax-ap-2013-special-senses'),
  lesson('external-middle-ear','External and middle ear','Follow sound from auricle through the ossicles to the oval window.',['auricle-ear','external-acoustic-meatus-ear','tympanic-membrane-ear','malleus-ear','incus-ear','stapes-ear','auditory-tube-ear','oval-window-ear','round-window-ear'],['Auricle funnels; tympanic membrane vibrates; ossicles bridge to the inner ear.'],['Malleus contacts tympanic membrane; stapes contacts oval window.'],['The auditory tube equalizes middle-ear pressure.'],['Oval and round windows are not the same opening; incus is between malleus and stapes.'], 'source-openstax-ap-2013-special-senses'),
  lesson('inner-ear','Cochlea and vestibular structures','Separate hearing structures in the cochlea from balance structures in vestibule and canals.',['cochlea-ear','vestibule-ear','utricle-ear','saccule-ear','semicircular-canals-ear','semicircular-ducts-ear','cochlear-duct-ear','vestibular-duct-ear','tympanic-duct-ear','organ-of-corti-ear','hair-cells-ear','vestibulocochlear-nerve-ear'],['Cochlea is spiral; semicircular canals form three looped planes; utricle and saccule occupy the vestibule. Utricle, saccule, and semicircular ducts serve equilibrium.'],['The cochlear duct lies between vestibular and tympanic scalae (ducts in this naming); the organ of Corti and hair cells sit in the cochlear duct, while vestibular and tympanic scalae belong to cochlear hearing anatomy.'],['Hair cells transduce mechanical movement into neural signals; cochlear duct and vestibular/tympanic scalae support hearing, while utricle, saccule, and semicircular ducts support equilibrium.'],['Cochlea is not a semicircular canal; utricle and saccule are vestibular sacs, and the vestibular duct is part of cochlear anatomy rather than an equilibrium duct.'], 'source-openstax-ap-2013-special-senses'),
  lesson('olfaction','Olfaction','Trace odor detection from receptor epithelium through bulb and cranial nerve I.',['olfactory-epithelium-sense','olfactory-receptor-sense','olfactory-bulb-sense','olfactory-nerve-sense'],['Olfactory receptors occupy specialized nasal epithelium; bulb is superior to it.'],['CN I fibers pass through the cribriform region to the bulb.'],['Receptor neurons transduce odor molecules before central processing.'],['Olfactory bulb is neural tissue, not the receptor epithelium.'], 'source-openstax-ap-2013-special-senses'),
  lesson('taste','Taste buds and taste nerves','Locate taste buds and associate regional taste fibers with cranial nerves.',['taste-bud-sense','gustatory-receptor-sense','facial-nerve-taste','glossopharyngeal-nerve-taste','vagus-nerve-taste'],['Taste buds are epithelial sensory structures; receptor cells occupy them.'],['CN VII carries much anterior-tongue taste; CN IX carries much posterior-tongue taste.'],['Multiple cranial nerves relay gustatory information from oral and pharyngeal regions.'],['A taste bud is not a cranial nerve; CN X contributes but is not the main anterior-tongue pathway.'], 'source-openstax-ap-2013-special-senses'),
  lesson('special-senses-integration','Special-sense integration','Use cranial-nerve labels and landmark relationships to keep sensory pathways distinct.',['optic-nerve-eye','optic-chiasm-sense','vestibulocochlear-nerve-ear','olfactory-nerve-sense','facial-nerve-taste','glossopharyngeal-nerve-taste','vagus-nerve-taste'],['CN I is smell, CN II vision, and CN VIII hearing/balance.'],['Optic nerves meet at the chiasm; taste fibers use VII, IX, and X by territory.'],['Peripheral receptors and cranial nerves create modality-specific routes.'],['Cranial nerve number does not identify a structure’s tissue type or location by itself.'], 'source-openstax-ap-2013-special-senses'),
];

